246	public class ValidateSettings {
247	    private static final Pattern FIGURE = Pattern.compile("\\d{1,15}(\\.\\d{1,2})?");
248	    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");
249	    private static final java.util.Set<String> DATED = java.util.Set.of(Settings.CLERK_LIMIT, Settings.FLOOR,
250	            Settings.TERMS, Settings.LATE_PCT, Settings.CAP, Settings.gradeTermsKey("A"), Settings.gradeTermsKey("B"),
251	            Settings.gradeTermsKey("C"), Settings.PROOF_THRESHOLD, Settings.NOTE_THRESHOLD);
252	
253	    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> body)
254	            throws InvalidSettingException {
255	        boolean limitChanged = request != null && request.clerkLimit() != null;
256	        BigDecimal limit = null;
257	        if (limitChanged && !request.clerkLimit().trim().isEmpty()) {
258	            String value = request.clerkLimit().trim();
259	            if (!FIGURE.matcher(value).matches()) {
260	                throw new InvalidSettingException("A clerk limit is 0.00 or more, with up to two decimals");
261	            }
262	            limit = new BigDecimal(value).setScale(2);
263	        }
264	        BigDecimal floor = null;
265	        if (request != null && request.floor() != null) {
266	            String value = request.floor().trim();
267	            if (!FIGURE.matcher(value).matches()) {
268	                throw new InvalidSettingException("A floor is 0.00 or more, with up to two decimals");
269	            }
270	            floor = new BigDecimal(value).setScale(2);
271	        }
272	        Integer terms = null;
273	        if (request != null && request.terms() != null) {
274	            String value = request.terms().trim();
275	            if (!DAYS.matcher(value).matches()) {
276	                throw new InvalidSettingException("Terms are a whole number of days, 0 or more");
277	            }
278	            terms = Integer.valueOf(value);
279	        }
280	        BigDecimal latePct = null;
281	        if (request != null && request.latePct() != null) {
282	            String value = request.latePct().trim();
283	            if (!FIGURE.matcher(value).matches()) {
284	                throw new InvalidSettingException("A late percent is 0.00 or more, with up to two decimals");
285	            }
286	            latePct = new BigDecimal(value).setScale(2);
287	        }
288	        boolean policyChanged = request != null && request.policyDate() != null;
289	        LocalDate policyDate = null;
290	        if (policyChanged && !request.policyDate().trim().isEmpty()) {
291	            try {
292	                policyDate = LocalDate.parse(request.policyDate().trim());
293	            } catch (DateTimeParseException e) {
294	                throw new InvalidSettingException("A policy date is a date, yyyy-MM-dd, or blank");
295	            }
296	        }
297	        boolean numberingChanged = request != null && request.periodNumberingFrom() != null;
298	        LocalDate numberingFrom = null;
299	        if (numberingChanged && !request.periodNumberingFrom().trim().isEmpty()) {
300	            try {
301	                numberingFrom = LocalDate.parse(request.periodNumberingFrom().trim());
302	            } catch (DateTimeParseException e) {
303	                throw new InvalidSettingException("A period numbering from is a date, yyyy-MM-dd, or blank");
304	            }
305	        }
306	        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
307	        if (request != null && request.gradeTerms() != null) {
308	            for (String grade : request.gradeTerms().keySet()) {
309	                if (!Settings.GRADES.contains(grade)) throw new InvalidSettingException("A grade is one of A, B or C");
310	            }
311	            for (String grade : Settings.GRADES) {
312	                String value = request.gradeTerms().get(grade);
313	                if (value == null) continue;
314	                value = value.trim();
315	                if (value.isEmpty()) {
316	                    gradeTerms.put(grade, null);
317	                } else if (!DAYS.matcher(value).matches()) {
318	                    throw new InvalidSettingException("Terms are a whole number of days, 0 or more, or blank");
319	                } else {
320	                    gradeTerms.put(grade, Integer.valueOf(value));
321	                }
322	            }
323	        }
324	        boolean capChanged = request != null && request.cap() != null;
325	        BigDecimal cap = null;
326	        if (capChanged && !request.cap().trim().isEmpty()) {
327	            String value = request.cap().trim();
328	            if (!FIGURE.matcher(value).matches()) {
329	                throw new InvalidSettingException("A cap is 0.00 or more, with up to two decimals, or blank");
330	            }
331	            cap = new BigDecimal(value).setScale(2);
332	        }
333	        boolean thresholdChanged = request != null && request.proofThreshold() != null;
334	        BigDecimal threshold = null;
335	        if (thresholdChanged && !request.proofThreshold().trim().isEmpty()) {
336	            String value = request.proofThreshold().trim();
337	            if (!FIGURE.matcher(value).matches()) {
338	                throw new InvalidSettingException("A proof threshold is 0.00 or more, with up to two decimals, or blank");
339	            }
340	            threshold = new BigDecimal(value).setScale(2);
341	        }
342	        boolean noteThresholdChanged = request != null && request.noteThreshold() != null;
343	        BigDecimal noteThreshold = null;
344	        if (noteThresholdChanged && !request.noteThreshold().trim().isEmpty()) {
345	            String value = request.noteThreshold().trim();
346	            if (!FIGURE.matcher(value).matches()) {
347	                throw new InvalidSettingException("A note threshold is 0.00 or more, with up to two decimals, or blank");
348	            }
349	            noteThreshold = new BigDecimal(value).setScale(2);
350	        }
351	        Map<String, String> perms = new LinkedHashMap<>();
352	        if (request != null && request.perms() != null) {
353	            for (String action : request.perms().keySet()) {
354	                if (!Settings.ACTIONS.contains(action)) {
355	                    throw new InvalidSettingException("An action is one of " + String.join(", ", Settings.ACTIONS));
356	                }
357	            }
358	            for (String action : Settings.ACTIONS) {
359	                String value = request.perms().get(action);
360	                if (value == null) continue;
361	                value = value.trim();
362	                java.util.List<String> roles = new java.util.ArrayList<>();
363	                if (!value.isEmpty()) {
364	                    for (String role : value.split(",", -1)) {
365	                        role = role.trim();
366	                        if (!Role.CLERK.equals(role) && !Role.STEWARD.equals(role)) {
367	                            throw new InvalidSettingException("Roles are clerk or steward, separated by commas, or blank");
368	                        }
369	                        if (!roles.contains(role)) roles.add(role);
370	                    }
371	                }
372	                perms.put(action, String.join(",", roles));
373	            }
374	        }
375	        boolean graceChanged = request != null && request.graceDays() != null;
376	        Integer graceDays = null;
377	        if (graceChanged && !request.graceDays().trim().isEmpty()) {
378	            String value = request.graceDays().trim();
379	            if (!DAYS.matcher(value).matches()) {
380	                throw new InvalidSettingException("Grace days are a whole number of days, 0 or more, or blank");
381	            }
382	            graceDays = Integer.valueOf(value);
383	        }
384	        Map<String, LocalDate> from = new LinkedHashMap<>();
385	        if (request != null && request.from() != null) {
386	            for (Map.Entry<String, String> entry : request.from().entrySet()) {
387	                if (!DATED.contains(entry.getKey())) throw new InvalidSettingException("Only a figure setting has a from-date");
388	                String value = entry.getValue() == null ? "" : entry.getValue().trim();
389	                if (value.isEmpty()) continue;
390	                try {
391	                    from.put(entry.getKey(), LocalDate.parse(value));
392	                } catch (DateTimeParseException e) {
393	                    throw new InvalidSettingException("A from-date is a date, yyyy-MM-dd, or blank");
394	                }
395	            }
396	        }
397	        body.set(new SettingsInput(limitChanged, limit, floor, terms, latePct, policyChanged, policyDate,
398	                numberingChanged, numberingFrom, gradeTerms, capChanged, cap, from,
399	                thresholdChanged, threshold, perms, graceChanged, graceDays, noteThresholdChanged, noteThreshold));
400	    }
401	}
