545	/**
546	 * Records each setting saved, with the value saved (blank for no clerk limit): the clerk limit, then
547	 * the floor, then the terms, then the late percent, then the policy date, then the period numbering
548	 * from, then each grade's terms (blank for the sheet's), then the cap (blank for none), then the proof threshold (blank for none), then the note threshold (blank for none), then each
549	 * action's entry in the permission matrix (blank for the standing rule, never dated), then the grace
550	 * days (blank for off, never dated); a figure
551	 * setting saved from a from-date given ends with it. Runs after every rule has passed, so a refused
552	 * change writes nothing.
553	 */
554	public class AuditSettingChanged {
555	    public void audit(@Val Sheet sheet, @Val SettingsInput input, @Val Settings settings,
556	            HttpServletRequest request, Audit audit) {
557	        String head = "SETTING_CHANGED sheet=" + sheet.id() + " by=" + Audit.user(request);
558	        input.datedValues().forEach((key, value) -> audit.record(line(head, key, value, input)));
559	        if (input.policyDateChanged()) {
560	            audit.record(head + " key=policy-date value=" + (input.policyDate() == null ? "" : input.policyDate()));
561	        }
562	        if (input.periodNumberingFromChanged()) {
563	            audit.record(head + " key=period-numbering-from value="
564	                    + (input.periodNumberingFrom() == null ? "" : input.periodNumberingFrom()));
565	        }
566	        input.gradeTermsValues().forEach((key, value) -> audit.record(line(head, key, value, input)));
567	        if (input.capValue() != null) audit.record(line(head, Settings.CAP, input.capValue(), input));
568	        if (input.proofThresholdValue() != null) {
569	            audit.record(line(head, Settings.PROOF_THRESHOLD, input.proofThresholdValue(), input));
570	        }
571	        if (input.noteThresholdValue() != null) {
572	            audit.record(line(head, Settings.NOTE_THRESHOLD, input.noteThresholdValue(), input));
573	        }
574	        input.perms().forEach((action, roles) -> audit.record(head + " key=" + Settings.permKey(action) + " value=" + roles));
575	        if (input.graceDaysChanged()) {
576	            audit.record(head + " key=grace-days value=" + (input.graceDays() == null ? "" : input.graceDays()));
577	        }
578	    }
579	
580	    private static String line(String head, String key, String value, SettingsInput input) {
581	        LocalDate from = input.from().get(key);
582	        return head + " key=" + key + " value=" + value + (from == null ? "" : " from=" + from);
583	    }
584	}
585	package net.officefloor.hq.app.setting;
586	
587	import java.time.LocalDate;
588	import java.util.HashMap;
589	import java.util.List;
590	import java.util.Map;
591	import java.util.NavigableMap;
592	import java.util.TreeMap;
593	import org.springframework.jdbc.core.JdbcTemplate;
594	import org.springframework.jdbc.core.RowCallbackHandler;
595	import org.springframework.stereotype.Repository;
596	
597	/** The settings store: the dated values in setting_value, the undated ones on the sheet's row. */
598	@Repository
599	public class SettingsRepository {
600	
601	    private final JdbcTemplate jdbc;
602	
603	    public SettingsRepository(JdbcTemplate jdbc) {
604	        this.jdbc = jdbc;
605	    }
606	
607	    public Settings find(String sheetId) {
608	        Map<String, NavigableMap<LocalDate, String>> dated = new HashMap<>();
609	        jdbc.query("SELECT setting_key, from_date, setting_value FROM setting_value WHERE sheet_id = ?",
610	                (RowCallbackHandler) (rs) -> dated.computeIfAbsent(rs.getString("setting_key"), (k) -> new TreeMap<>())
611	                        .put(rs.getDate("from_date").toLocalDate(), rs.getString("setting_value")), sheetId);
612	        Map<String, String> perms = new HashMap<>();
613	        jdbc.query("SELECT action, roles FROM setting_perm WHERE sheet_id = ?",
614	                (RowCallbackHandler) (rs) -> perms.put(rs.getString("action"), rs.getString("roles")), sheetId);
615	        List<Settings> found = jdbc.query("SELECT today, policy_date, period_numbering_from, grace_days FROM sheet WHERE id = ?",
616	                (rs, n) -> new Settings(sheetId, rs.getDate("today").toLocalDate(), dated,
617	                        rs.getDate("policy_date") == null ? null : rs.getDate("policy_date").toLocalDate(),
618	                        rs.getDate("period_numbering_from") == null ? null : rs.getDate("period_numbering_from").toLocalDate(), perms,
619	                        rs.getObject("grace_days", Integer.class)),
620	                sheetId);
621	        return found.isEmpty() ? new Settings(sheetId, null, dated, null, null, perms, null) : found.get(0);
622	    }
623	
624	    /** Records a dated setting's value from a date, replacing any value already recorded from it. */
625	    public void record(String sheetId, String key, LocalDate from, String value) {
626	        jdbc.update("MERGE INTO setting_value (sheet_id, setting_key, from_date, setting_value) KEY (sheet_id, setting_key, from_date) VALUES (?, ?, ?, ?)",
627	                sheetId, key, java.sql.Date.valueOf(from), value);
628	        history(sheetId, key, from, value);
629	    }
630	
631	    /** Keeps a setting's value in its history, with the sheet's today now. */
632	    private void history(String sheetId, String key, LocalDate from, String value) {
633	        jdbc.update("INSERT INTO setting_history (sheet_id, setting_key, from_date, setting_value, set_on)"
634	                + " VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
635	                sheetId, key, from == null ? null : java.sql.Date.valueOf(from), value, sheetId);
636	    }
637	
638	    /**
639	     * The sheet's settings as they stood at the end of {@code day}: each dated value and the policy
640	     * date as last recorded while the sheet's today was on or before it, and that date standing in for
641	     * the sheet's today. The others are as they are now.
642	     */
643	    public Settings findAsOf(String sheetId, LocalDate day) {
644	        Settings now = find(sheetId);
645	        Map<String, NavigableMap<LocalDate, String>> dated = new HashMap<>();
646	        LocalDate[] policy = { null };
647	        boolean[] policyKept = { false };
648	        jdbc.query("SELECT setting_key, from_date, setting_value, set_on FROM setting_history WHERE sheet_id = ? ORDER BY id",
649	                (RowCallbackHandler) (rs) -> {
650	                    String key = rs.getString("setting_key");
651	                    String value = rs.getString("setting_value");
652	                    boolean counts = !rs.getDate("set_on").toLocalDate().isAfter(day);
653	                    if (POLICY_DATE.equals(key)) {
654	                        policyKept[0] = true;
655	                        if (counts) policy[0] = value.isBlank() ? null : LocalDate.parse(value);
656	                    } else if (counts) {
657	                        dated.computeIfAbsent(key, (k) -> new TreeMap<>()).put(rs.getDate("from_date").toLocalDate(), value);
658	                    }
659	                }, sheetId);
660	        return new Settings(sheetId, day, dated, policyKept[0] ? policy[0] : now.policyDate(),
661	                now.periodNumberingFrom(), now.perms(), now.graceDays());
662	    }
663	
664	    private static final String POLICY_DATE = "policy-date";
665	
666	    /** Records the roles ('' for the standing rule) that may take an action. */
667	    public void recordPerm(String sheetId, String action, String roles) {
668	        jdbc.update("MERGE INTO setting_perm (sheet_id, action, roles) KEY (sheet_id, action) VALUES (?, ?, ?)",
