689	/**
690	 * Saves the settings being changed, leaving the others as they are: a figure setting's value is
691	 * recorded from its from-date (the sheet's today when none is given), keeping the values recorded
692	 * from other dates and replacing one recorded from the same date. An action's entry in the
693	 * permission matrix is not dated: it replaces the one before.
694	 */
695	public class SaveSettings {
696	    public void save(@Val SettingsInput input, @Val Sheet sheet, SettingsRepository repository,
697	            Out<Settings> settingsOut) {
698	        Settings now = repository.find(sheet.id());
699	        if (input.policyDateChanged() || input.periodNumberingFromChanged() || input.graceDaysChanged()) {
700	            repository.saveUndated(new Settings(sheet.id(), now.today(), now.dated(),
701	                    input.policyDateChanged() ? input.policyDate() : now.policyDate(),
702	                    input.periodNumberingFromChanged() ? input.periodNumberingFrom() : now.periodNumberingFrom(), now.perms(),
703	                    input.graceDaysChanged() ? input.graceDays() : now.graceDays()));
704	        }
705	        input.perms().forEach((action, roles) -> repository.recordPerm(sheet.id(), action, roles));
